INSERT INTO collections (slug, name, department, description, hero_image, sort_order) VALUES
('women', 'Women', 'women', 'Dresses, denim, knits and everything in between.', '/images/editorial/editorial-01.webp', 1),
('men', 'Men', 'men', 'Tees, chinos, layers and jackets built to wear hard.', '/images/editorial/editorial-02.webp', 2),
('kids', 'Kids', 'kids', 'Play-proof clothes for ages 4 to 14.', '/images/editorial/editorial-03.webp', 3),
('baby', 'Baby', 'baby', 'Soft organic basics for 0 to 24 months.', '/images/editorial/editorial-04.webp', 4),
('maternity', 'Maternity', 'maternity', 'Bump-friendly fits for every trimester.', '/images/editorial/editorial-05.webp', 5),
('denim', 'Denim', NULL, 'Riverbend Denim in every fit and wash.', '/images/editorial/editorial-06.webp', 6),
('activewear', 'Activewear', NULL, 'Otter Active gear for runs, lifts and rest days.', '/images/editorial/editorial-07.webp', 7),
('sale', 'Sale', NULL, 'Markdowns across the store. Prices as marked.', '/images/editorial/editorial-08.webp', 8),
('new-arrivals', 'New Arrivals', NULL, 'Just landed this week.', '/images/editorial/editorial-09.webp', 9),
('essentials-forever', 'Essentials Forever', NULL, 'Everyday tees at an everyday price, never discounted.', '/images/editorial/editorial-10.webp', 10),
('gift-cards', 'Gift Cards', NULL, 'Let them pick.', '/images/editorial/editorial-11.webp', 11);
